mapper.insert:
INSERT INTO analysis_run (
    sync_request_id, attempt_no, idempotency_key, run_type, mode
) VALUES (
    #{syncRequestId}, #{attemptNo}, #{idempotencyKey}, #{runType}, #{mode}
)

INSERT INTO analysis_run (
    backfill_request_id, attempt_no, idempotency_key, run_type, mode
) VALUES (
    #{backfillRequestId}, #{attemptNo}, #{idempotencyKey}, #{runType}, #{mode}
)

mapper.select:
SELECT * FROM analysis_run
WHERE backfill_request_id = #{backfillRequestId}
ORDER BY attempt_no DESC LIMIT 1
